# area: narrowing_user
# hypothesis: TypeIs narrows the else branch to the complement type while TypeGuard leaves it unchanged, and both narrowings hold when the guard calls sit inside nested function scopes.
from typing import TypeGuard, TypeIs, assert_type, reveal_type


def is_str_is(val: int | str) -> TypeIs[str]:
    return isinstance(val, str)


def is_str_guard(val: int | str) -> TypeGuard[str]:
    return isinstance(val, str)


def outer(value: int | str) -> tuple[str, str]:
    def inner_is() -> str:
        if is_str_is(value):
            assert_type(value, str)
            return value.upper()
        assert_type(value, int)
        return str(value + 1)

    def inner_guard() -> str:
        if is_str_guard(value):
            assert_type(value, str)
            return value.upper()
        reveal_type(value)
        return str(value)

    return inner_is(), inner_guard()


print(outer(3))
print(outer('ab'))
